fn mul_all(xs: list) -> i64 {
    let num = 0;
    let res = 0;
    while res < len(xs) {
        num = num + xs[res];
        res = res + 1;
    }
    return num;
}
fn main() -> i64 {
    let data: list = [5, 5, 1];
    println(mul_all(data));
    return 0;
}

