fn run(xs: list) -> i64 {
    let u = 0;
    let s = 0;
    while s < len(xs) {
        u = u - xs[s];
        s = s + 1;
    }
    return u;
}
fn main() -> i64 {
    let data: list = [-9, 0, 0, -2];
    println(run(data));
    return 0;
}

