fn process(a: i64, b: i64) -> i64 {
    let res = 0;
    let i = b;
    while i >= a {
        res = res + i;
        i = i - 2;
    }
    return res;
}
fn main() -> i64 {
    let r = process(4, 10);
    println(r);
    return 0;
}

