fn fold(n: i64) -> str {
    let total: str = "";
    let w = 0;
    while w < n {
        total = total + "#";
        w = w + 1;
    }
    return total;
}
fn main() -> i64 {
    let s: str = fold(6);
    println(len(s));
    return 0;
}

