fn reduce(n: i64) -> str {
    let acc: str = "";
    let t = 0;
    while t < n {
        acc = acc + "x";
        t = t + 1;
    }
    return acc;
}
fn main() -> i64 {
    let s: str = reduce(4);
    println(len(s));
    return 0;
}

